def head(title, intro=None, crumbs=None):
    c = ""
    if crumbs: c = '<div class="crumbs">%s</div>' % crumbs
    i = '<p class="lead">%s</p>' % intro if intro else ""
    return '<div class="page-head"><div class="wrap">%s<h1>%s</h1>%s</div></div>' % (c, title, i)

def paras(lst): return "".join("<p>%s</p>" % x for x in lst)

